import json, pandas as pd
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.lib import colors
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Image, Table, TableStyle, PageBreak, KeepTogether
R=json.load(open("results.json")); st=getSampleStyleSheet()
B=ParagraphStyle("B",parent=st["BodyText"],fontSize=9.5,leading=13,alignment=4,spaceAfter=6)
H1=ParagraphStyle("H1",parent=st["Heading1"],fontSize=13,spaceBefore=10,spaceAfter=5); C=ParagraphStyle("C",parent=B,fontSize=8,leading=10,alignment=1,textColor=colors.HexColor("#444"))
Tt=ParagraphStyle("T",parent=st["Title"],fontSize=18,leading=22); Sm=ParagraphStyle("S",parent=B,fontSize=8.5,leading=11)
fig=lambda n,w,cap:KeepTogether([Image(f"figures/{n}.png",width=w*inch,height=w*inch*__import__("PIL.Image",fromlist=["x"]).open(f"figures/{n}.png").size[1]/__import__("PIL.Image",fromlist=["x"]).open(f"figures/{n}.png").size[0]),Paragraph(cap,C),Spacer(1,6)])
def tbl(rows,cw=None):
    t=Table(rows,colWidths=cw,repeatRows=1); t.setStyle(TableStyle([("FONTSIZE",(0,0),(-1,-1),7.5),("BACKGROUND",(0,0),(-1,0),colors.HexColor("#dfe9f3")),("GRID",(0,0),(-1,-1),.25,colors.grey),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold")])); return t
m=pd.DataFrame(R["models"]); e=R["effects"]; c=R["classification"]; sg=pd.DataFrame(R["segments"]).sort_values("delay",ascending=False); sim=pd.DataFrame(R["sim"])
g=lambda mod,h,col: m[(m.model==mod)&(m.horizon==h)][col].iloc[0]
S=[]; P=lambda t,s=B:S.append(Paragraph(t,s))
S+= [Paragraph("Forecasting and Managing Traffic Congestion in a Ventura County Corridor Network: A Simulation-Based Data Science Study",Tt),
Paragraph("Traffic Intelligence Project &mdash; technical report (pipeline-validation study)",C),Spacer(1,8)]
P("<b>Important scope note.</b> The network, observations, incidents, and weather in this report are <b>synthetic</b>: produced by a mechanistic simulator with stylised Ventura County corridors. Nothing here is a measured finding about real Ventura traffic. The contribution is a reproducible, documented pipeline (dataset schema, models, evaluation, simulation, dashboard) that can be re-pointed at real sources such as NPMRDS, Caltrans PeMS, and NOAA.",Sm)
S.append(Paragraph("Abstract",H1))
P(f"We construct a 15-minute traffic dataset for 12 stylised road segments (nine highway/freeway, three arterial) over January&ndash;June 2025 (208,512 segment-intervals; 309 incidents) and use it to study three questions: when and where congestion forms, whether it can be forecast 15, 30 and 60 minutes ahead, and whether adaptive signal control reduces arterial delay. On a May&ndash;June hold-out, gradient boosting with network-neighbour features achieves a 60-minute speed MAE of {g('Gradient boosting + graph features','60 min','mae'):.2f} mph versus {g('Persistence','60 min','mae'):.2f} mph for persistence, and classifies 60-minute-ahead congestion level with macro-F1 {c['gb_f1']:.2f} (persistence {c['persist_f1']:.2f}). A within-segment regression recovers the simulator's built-in effects of rain and incidents, validating the estimation code. A queue simulation shows max-pressure control cutting mean delay under tidal demand from {sim[(sim.scenario=='tidal')].mean_delay_s.iloc[0]:.0f} s to {sim[(sim.scenario=='tidal')].mean_delay_s.iloc[2]:.0f} s per vehicle, with little benefit during a capacity-reduction incident.")
S.append(Paragraph("1. Introduction",H1))
P("Congestion imposes delay, fuel use, and emissions, and data science addresses it at three layers: perception (sensing speeds and volumes), prediction (spatial-temporal forecasting), and control (signal timing and routing). Deployed systems such as SURTRAC in Pittsburgh show adaptive signal control can reduce travel times (Smith et al., 2013), and graph-based forecasters such as DCRNN (Li et al., 2018) exploit road-network structure. This project packages a small, fully reproducible version of that stack for a corridor network patterned on Ventura County, California.")
fig_ = fig("fig_pipeline",6.8,"Figure 1. End-to-end pipeline."); S.append(fig_)
S.append(Paragraph("2. Data",H1))
P("<b>Simulator.</b> Demand on each segment follows weekday AM/PM peak profiles, a weekend profile, holidays (five dates), daily and autocorrelated noise. Speed follows a BPR-style volume/capacity relation, <i>v = v<sub>f</sub> / (1 + 0.6 (V/C)<super>5</super>)</i> (Bureau of Public Roads, 1964), smoothed in time. Capacity falls with rain (&minus;5% to &minus;23%) and during incidents (capacity multipliers 0.3&ndash;0.8). Congestion on a downstream segment reduces capacity on its upstream neighbour (queue spillback), and freeway congestion diverts demand to a parallel arterial. Rain is generated as seasonal storm events (wetter in winter). Emissions use a speed-dependent fuel-economy curve.")
P("<b>Tables.</b> <font face='Courier'>observations.csv</font> (208,512 rows, 18 fields), <font face='Courier'>segments.csv</font>, <font face='Courier'>weather.csv</font>, <font face='Courier'>incidents.csv</font>, <font face='Courier'>signals.csv</font> (27 pretimed signals). Congestion level 0&ndash;4 is defined from speed/free-flow ratio thresholds of 0.85, 0.70, 0.55, 0.40. Delay is vehicle-hours relative to free flow.")
S.append(fig("fig_network",5.4,"Figure 2. Stylised network with hotspot clusters (k-means on weekday hourly travel-time-index profiles)."))
S.append(Paragraph("3. Methods",H1))
P("<b>Descriptive analysis and hotspots.</b> Delay = volume &times; length &times; (1/speed &minus; 1/free-flow speed), summed over time. Segments are clustered by 24-hour weekday travel-time-index profile (k-means, k=3). <b>Effects.</b> log travel time is regressed on light-rain (0.05&ndash;0.5 mm/15 min), heavy-rain (&gt;0.5) and incident indicators after removing segment&times;day-of-week&times;quarter-hour means (a within estimator); 95% intervals use a 100-replicate day-block bootstrap. <b>Forecasting.</b> Targets are speed at t+15, t+30, t+60 min. Features: current and lagged speeds (up to 8 steps and one day), volume, incident flags, rain, cyclic time, holiday, and static road attributes; graph variants add mean normalised speed of upstream and downstream neighbours. Models: persistence, ridge, random forest, and histogram gradient boosting (an XGBoost-style learner from scikit-learn) with and without graph features. Train: Jan&ndash;Apr; test: May&ndash;Jun (chronological split, no shuffling). <b>Signal control.</b> A one-second two-phase queue model compares fixed-time, demand-split (Webster-style; Webster, 1958) and max-pressure control (Varaiya, 2013), 30 replications per cell.")
S.append(Paragraph("4. Results",H1))
P(f"<b>4.1 Congestion patterns.</b> Delay concentrates on the US-101 segments; the highest is {sg.iloc[0].segment_name} ({sg.iloc[0].delay/1000:.0f}k vehicle-hours), followed by {sg.iloc[1].segment_name} ({sg.iloc[1].delay/1000:.0f}k). Total simulated delay is {R['total_delay_veh_h']/1000:.0f}k vehicle-hours and {R['total_co2_t']:.0f} t CO<sub>2</sub> over six months. Peaks are weekday mornings and afternoons (Fig. 3). These patterns are properties of the simulator's demand assumptions.")
S.append(fig("fig_heatmap",5.8,"Figure 3. Network-mean travel time index by day and hour."))
S.append(fig("fig_delay",5.8,"Figure 4. Delay by segment (red freeway, blue arterial, grey highway)."))
S.append(fig("fig_week",5.8,"Figure 5. One week on segment 3 with incident and rain shading."))
P(f"<b>4.2 Rain and incidents.</b> Light rain raises travel time by {e['rain_light']['pct']:.1f}% (95% CI {e['rain_light']['lo']:.1f}&ndash;{e['rain_light']['hi']:.1f}), heavy rain by {e['rain_heavy']['pct']:.1f}% ({e['rain_heavy']['lo']:.1f}&ndash;{e['rain_heavy']['hi']:.1f}) and active incidents by {e['incident']['pct']:.1f}% ({e['incident']['lo']:.1f}&ndash;{e['incident']['hi']:.1f}). Because the simulator encodes these mechanisms, this is a check that the estimator recovers known effects; on real data the same code would give empirical estimates, with the usual confounding caveats.")
S.append(fig("fig_effects",3.8,"Figure 6. Estimated effects on travel time."))
rows=[["Model","Horizon","MAE (mph)","RMSE","R2","MAE congested"]]+[[r.model,r.horizon,f"{r.mae:.2f}",f"{r.rmse:.2f}",f"{r.r2:.3f}",f"{r.mae_congested:.2f}"] for r in m.itertuples()]
P(f"<b>4.3 Forecasting.</b> All learned models beat persistence, and the advantage grows with horizon (Table 1, Fig. 7). At 60 minutes, gradient boosting with graph features has MAE {g('Gradient boosting + graph features','60 min','mae'):.2f} mph versus {g('Persistence','60 min','mae'):.2f} (persistence) and {g('Ridge regression','60 min','mae'):.2f} (ridge). Graph features give a small gain overall (60-min MAE {g('Gradient boosting (no graph)','60 min','mae'):.2f} to {g('Gradient boosting + graph features','60 min','mae'):.2f}) and a larger one on congested intervals ({g('Gradient boosting (no graph)','60 min','mae_congested'):.2f} to {g('Gradient boosting + graph features','60 min','mae_congested'):.2f}). Gains are modest partly because the simulator's spillback is simple. For congestion level 60 min ahead, accuracy is {c['gb_acc']:.3f} vs {c['persist_acc']:.3f} and macro-F1 {c['gb_f1']:.2f} vs {c['persist_f1']:.2f}; most errors are between adjacent levels (Fig. 9). Incident onsets are unpredictable from the features, so the models mainly learn recurring structure.")
S+= [KeepTogether([Paragraph("Table 1. Hold-out performance (May&ndash;June 2025, simulated data).",C),tbl(rows,[2.2*inch,.7*inch,.8*inch,.6*inch,.6*inch,1*inch])]),Spacer(1,6)]
S.append(fig("fig_models",5.8,"Figure 7. Test MAE by model and horizon."))
S.append(fig("fig_forecast",5.8,"Figure 8. Actual vs 60-minute forecast over three held-out days."))
S.append(fig("fig_importance",3.6,"Figure 9a. Permutation feature importance."))
S.append(fig("fig_confusion",3.0,"Figure 9. Confusion matrix for 60-minute congestion level."))
S.append(Paragraph("5. Signal-control simulation",H1))
rows=[["Scenario","Controller","Mean delay (s/veh)","95% CI","Mean queue","Peak queue"]]+[[r.scenario,r.controller,f"{r.mean_delay_s:.1f}",f"&plusmn;{r.ci95:.1f}",f"{r.mean_total_queue:.1f}",f"{r.max_total_queue:.0f}"] for r in sim.itertuples()]
P("Arrival rates are stylised (0.28 veh/s per phase balanced; 0.55/0.18 veh/s tidal swap; 40% capacity cut on one approach for 40 minutes), <b>not</b> calibrated to the dataset. Max-pressure control is far better when demand is unbalanced or shifts over time, because pretimed plans cannot adapt. The demand-split plan equals the fixed plan here because scenario-average demand is symmetric, which illustrates why pretimed plans fail on time-varying demand. During the incident all controllers perform similarly: when one approach is capacity-limited, timing cannot create capacity.")
S+= [KeepTogether([Paragraph("Table 2. Signal control results.",C),tbl(rows,[.8*inch,2*inch,1.1*inch,.7*inch,.8*inch,.8*inch])]),Spacer(1,6)]
S.append(fig("fig_signal_sim",6.4,"Figure 10. Mean queue over time by scenario (30 replications)."))
S.append(Paragraph("6. Limitations",H1))
P("(1) All data are simulated, so absolute numbers (delay, speeds, effect sizes) describe the simulator, not Ventura. (2) Models see simulator noise that is simpler than real sensor error, missing data, and detector faults. (3) Feature importance and gains from graph features depend on the spillback rule built into the simulator. (4) The signal model is a single isolated two-phase intersection with no turning movements, pedestrians, or coordination. (5) No LSTM or graph neural network was trained; the graph-feature gradient-boosting model is a lightweight stand-in. (6) The speed function lets breakdown-regime speeds fall to a few mph, so delay totals are inflated relative to typical real freeway data and should be read as relative rankings only. (7) Bootstrap intervals ignore spatial dependence across segments.")
S.append(Paragraph("7. Reproducing with real data",H1))
P("Replace <font face='Courier'>data/observations.csv</font> with real 15-minute segment data using the same field names (see <font face='Courier'>docs/DATA_DICTIONARY.md</font> and <font face='Courier'>docs/REAL_DATA_GUIDE.md</font>): travel times and speeds from NPMRDS or PeMS, hourly weather from NOAA, and incident logs from Caltrans/CHP. Scripts 02&ndash;05 then run unchanged apart from segment metadata and the holiday list. Real-data evaluation should add spatial cross-validation, calibration of forecast uncertainty, and comparison with deep spatial-temporal baselines.")
S.append(Paragraph("References",H1))
for r in ["Bureau of Public Roads (1964). <i>Traffic Assignment Manual</i>. U.S. Department of Commerce.","Breiman, L. (2001). Random forests. <i>Machine Learning</i>, 45, 5&ndash;32.","Li, Y., Yu, R., Shahabi, C., Liu, Y. (2018). Diffusion convolutional recurrent neural network: data-driven traffic forecasting. <i>ICLR</i>.","Pedregosa, F. et al. (2011). Scikit-learn: machine learning in Python. <i>JMLR</i>, 12, 2825&ndash;2830.","Smith, S. F., Barlow, G. J., Xie, X.-F., Rubinstein, Z. B. (2013). SURTRAC: scalable urban traffic control. <i>TRB Annual Meeting</i>.","Varaiya, P. (2013). Max pressure control of a network of signalized intersections. <i>Transportation Research Part C</i>, 36, 177&ndash;195.","Webster, F. V. (1958). <i>Traffic Signal Settings</i>. Road Research Technical Paper No. 39, HMSO."]: P(r,Sm)
SimpleDocTemplate("outputs/Traffic_Congestion_Research_Paper.pdf",pagesize=letter,leftMargin=.9*inch,rightMargin=.9*inch,topMargin=.8*inch,bottomMargin=.8*inch,title="Forecasting and Managing Traffic Congestion (simulation study)").build(S)
